function validate(input) {
  const [{ Transactions = [] }] = input;
  const seen = new Set();
  for (const [user, spend, date] of Transactions) {
    if (user === null) return 'user_id cannot be null.';
    if (typeof spend !== 'number' || spend < 0 || spend > 999.99 || Math.abs(Math.round(spend * 100) - spend * 100) > 1e-6) return `spend ${spend} must be 0 to 999.99 with 2 decimals.`;
    if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2} ([01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(date)) return `transaction_date ${date} is not a datetime.`;
    const key = `${user}|${date}`;
    if (seen.has(key)) return `User ${user} has two transactions at ${date}.`;
    seen.add(key);
  }
  return null;
}

