function generate(rand, size) {
  const two = n => String(n).padStart(2, '0');
  const small = size === 'small';
  // Small cases reuse a few amounts so equal spends happen; large ones draw any cent value.
  const amounts = [7, 13.89, 37.33, 49.78, 65.56, 96, 100.44];
  const users = small ? 4 : 400;
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Transactions = [], seen = new Set();
  while (Transactions.length < count) {
    const user = 1 + Math.floor(rand() * users);
    const date = `2023-11-${two(1 + Math.floor(rand() * (small ? 4 : 30)))} ${two(Math.floor(rand() * 24))}:${two(Math.floor(rand() * 60))}:${two(Math.floor(rand() * 60))}`;
    const key = `${user}|${date}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const spend = small ? amounts[Math.floor(rand() * amounts.length)] : Math.floor(rand() * 100000) / 100;
    Transactions.push([user, spend, date]);
  }
  return [{ Transactions }];
}
